# Re-fetch yesterday's expenses from all groups to see details
import json
for g in groups_data:
    gid = g['group_id']
    resp = apis.splitwise.show_group_expenses(group_id=gid, access_token=splitwise_token, min_created_at=yesterday_str + 'T00:00:00', max_created_at=yesterday_str + 'T23:59:59')
    if resp:
        print(f"Group {gid} ({g['name']}):")
        for exp in resp:
            print(json.dumps(exp, indent=2))
    else:
        print(f"Group {gid} ({g['name']}): no expenses")

