# Let's fetch expenses for each group using the correct key 'group_id'
all_expenses = []
for group in groups_data:
    gid = group['group_id']
    resp = apis.splitwise.show_group_expenses(group_id=gid, access_token=splitwise_token, min_created_at=yesterday_str, max_created_at=today_str)
    print(f"Group {gid} ({group['name']}) response:", resp)
    # We'll inspect the structure; likely a list of expenses
    if isinstance(resp, list):
        all_expenses.extend(resp)
    elif isinstance(resp, dict) and 'expenses' in resp:
        all_expenses.extend(resp['expenses'])
    else:
        print("Unexpected response format")

print("All expenses count:", len(all_expenses))
for exp in all_expenses:
    print(exp)

