# Fetch all expenses from yesterday across all groups to map remaining Venmo transactions.
all_expenses = []
for g in groups:
    gid = g['group_id']
    resp = apis.splitwise.show_group_expenses(gid, splitwise_token, min_created_at=yesterday_str, max_created_at=today_str, page_limit=100)
    print(f"Group {gid} ({g['name']}): {resp}")
    # Assuming resp is a list of expenses; if it's a dict with 'expenses', handle accordingly.
    if isinstance(resp, list):
        all_expenses.extend(resp)
    elif isinstance(resp, dict) and 'expenses' in resp:
        all_expenses.extend(resp['expenses'])
    else:
        print("Unexpected response format")

